<script setup lang="ts">
import { watch,ref } from 'vue';import { X,Trash2 } from '@lucide/vue';import { useCartStore } from '@/stores/cart';import { api } from '@/api/http';import type { Address,Order } from '@/types';import { useRouter } from 'vue-router'
const router=useRouter(),open=defineModel<boolean>({default:false});const cart=useCartStore(),submitting=ref(false)
watch(open,value=>{if(value)cart.load()})
async function checkout(){if(!cart.items.length)return;submitting.value=true;try{const addresses=await api<Address[]>({url:'/user/addresses'});const address=addresses.find(x=>x.isDefault===1)||addresses[0];if(!address){open.value=false;await router.push({path:'/settings',query:{tab:'addresses'}});return}const order=await api<Order>({url:'/user/orders',method:'POST',data:{clientOrderNo:`web-${Date.now()}`,addressBookId:address.id,remark:'网页端订单'}});const payment=await api<{mode:string;status:string}>({url:`/user/orders/${order.id}/payment`,method:'POST'});alert(payment.status==='PAID'?'订单支付成功':'订单已创建，请在微信小程序完成支付');await cart.load();open.value=false}catch(e){alert((e as Error).message)}finally{submitting.value=false}}
</script>
<template><div v-if="open" class="drawer-mask" @click.self="open=false"><aside class="cart-drawer"><header><div><span>MY CART</span><h2>购物车</h2></div><button @click="open=false"><X/></button></header><div class="cart-list"><div v-if="!cart.items.length" class="empty-cart">还没有选择菜品</div><article v-for="item in cart.items"><div><b>{{item.dishName}}</b><small>¥{{item.unitPrice}} × {{item.quantity}}</small></div><strong>¥{{(item.unitPrice*item.quantity).toFixed(2)}}</strong></article></div><footer><button class="clear-cart" @click="cart.clear"><Trash2 :size="16"/>清空</button><div><small>合计</small><strong>¥{{cart.total.toFixed(2)}}</strong></div><button class="checkout" :disabled="submitting||!cart.items.length" @click="checkout">{{submitting?'提交中…':'去结算'}}</button></footer></aside></div></template>
